(()=>{
 const hero=document.getElementById('hero');
 const wrap=hero?.querySelector('.model-wrap');
 const male=wrap?.querySelector('.model');
 const female=wrap?.querySelector('.dz-female-model');
 const femaleBg=hero?.querySelector('.dz-female-bg');
 if(!hero||!wrap||!male||!female||!femaleBg)return;
 const park=document.createElement('div');park.className='dz-park-bg';hero.insertBefore(park,hero.querySelector('.wash'));
 const jumper=document.createElement('img');jumper.className='model dz-jumper-model';jumper.alt='Model nam phong cách streetwear đang nhảy';jumper.src='data:image/webp;base64,';wrap.appendChild(jumper);
 const h=hero.querySelector('.copy h1'),d=hero.querySelector('.copy .desc'),e=hero.querySelector('.copy .eyebrow');
 const original=[h?.innerHTML,d?.textContent,e?.textContent];
 const slides=[
   {title:original[0],desc:original[1],eyebrow:original[2]},
   {title:'Streetwear<br><em>in Motion.</em>',desc:'Nét cá tính giữa phố thị, tự do phối đồ theo phong cách Hàn Quốc.',eyebrow:'THE STREET EDIT • 2026'},
   {title:'Own Your<br><em>Moment.</em>',desc:'Streetwear năng động, cá tính và tự do trong từng chuyển động.',eyebrow:'THE URBAN EDIT • 2026'}
 ];
 let current=0,interval,revealTimer,sequence=0; window.dzActiveModel=()=>current;
 function setSlide(index){
   current=(index+3)%3;
   const mySequence=++sequence;
   clearTimeout(revealTimer);
   hero.classList.remove('dz-model-entering');
   hero.classList.add('dz-model-waiting');
   hero.classList.remove('dz-title-revealed');
   hero.classList.toggle('dz-female-active',current===1);
   hero.classList.toggle('dz-third-active',current===2);
   h.innerHTML=slides[current].title;
   d.textContent=slides[current].desc;
   e.textContent=slides[current].eyebrow;
   window.dispatchEvent(new CustomEvent('dz:modelchange',{detail:{index:current}}));
   requestAnimationFrame(()=>requestAnimationFrame(()=>{
     if(mySequence===sequence)hero.classList.add('dz-title-revealed');
   }));
   revealTimer=setTimeout(()=>{
     if(mySequence===sequence){
       hero.classList.remove('dz-model-waiting');
       hero.classList.add('dz-model-entering');
     }
   },1000);
 }
 function start(){clearInterval(interval);interval=setInterval(()=>{if(!document.hidden && document.getElementById('lookDialog')?.hidden!==false)setSlide(current+1)},5000)}
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)start()});
 setSlide(0);start();
})();
